import{z as s,x as o,o as B,c as d,q as n,j as i,D as t,d as E,s as A,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"生成模型校准市场","description":"","frontmatter":{"title":"生成模型校准市场","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/dp-generative-calibration.md","filePath":"quant/dp-generative-calibration.md","lastUpdated":1791413859000}'),p={name:"quant/dp-generative-calibration.md"};function u(h,a,m,F,c,b){const r=o("Mermaid");return B(),d("div",null,[a[2]||(a[2]=n('<h1 id="生成模型校准市场" tabindex="-1">生成模型校准市场 <a class="header-anchor" href="#生成模型校准市场" aria-label="Permalink to &quot;生成模型校准市场&quot;">​</a></h1><div class="epigraph"><p>校准的对象从十几个参数搬到了整条路径测度：不再只问「哪个模型贴近这张报价」，而问「哪个生成器长出与市场同分布的情景」——代价是验证从残差平方变成了分布距离加下游任务。</p><footer>—— 据 Horvath, Muguruza and Tomas, Quantitative Finance, 2021；Wiese et al., Quantitative Finance, 2020 整理</footer></div><p><a href="/quant/dp-rl-execution-deep">上一课</a>把执行 RL 收在环境构造上：策略的上限由仿真器的保真度决定。信号单元到此走完，课程进入定价与验证单元；第一件事是把「环境从哪来」从工程问题升格为建模问题。<a href="/quant/dupire">局部波动</a>与<a href="/quant/stochastic-volatility">随机波动</a>的经典校准把测度压进少数参数，病态时靠<a href="/quant/calibration-regularization">正则化</a>稳住；深度学习从两个方向改写这条链：把校准映射本身学成代理，或把市场直接学成生成器。本课写这两种「校准」各校的是什么、误差记在哪本账上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>第一个方向是代理校准：参数模型不变，变的是求逆的速度。训练网络学会「参数到价格或隐含波动」的正映射，市场报价进来后对网络反解参数——分钟级的数值优化降到毫秒级前向。难点在覆盖与精度：网络在训练参数域内插值极好、域外静默外推，落点检测与回退数值优化必须写进流程。第二个方向是生成校准：<a href="/quant/market-generator-vae">Market Generator</a>、<a href="/quant/sig-wasserstein-gan">Sig-Wasserstein GAN</a> 与 <a href="/quant/neural-sde">Neural SDE</a> 三条路线直接拟合路径测度，输出可抽样的情景族。测度纪律在这里最先崩：\\(\\mathbb{P}\\) 上训出的生成器长出的是「像历史的情景」，不是定价用的风险中性情景；拿 \\(\\mathbb{P}\\) 样本平均支付当价格，错得系统而无声。</p><p><span class="marginnote">术语翻译：「代理校准」就是先用原模型造大量「参数→价格」的例题，训一个网络背下这张对照表；之后市场报价一来，网络一步给出参数，不必再跑分钟级的数值优化。</span></p><h3 id="两本误差账" tabindex="-1">两本误差账 <a class="header-anchor" href="#两本误差账" aria-label="Permalink to &quot;两本误差账&quot;">​</a></h3><p>代理校准的误差是「与原模型价格差多少」，对照物是参数模型自己；生成校准的误差是「与真实市场分布差多少」，对照物是留出的真实路径。两本账不能混着报：用分布距离小去担保报价精度，或用贴报价去担保情景质量，都是记账错误。</p><p><span class="marginnote">数字实例：数值法校准一次 Heston 要反复解正定价，耗时分钟级；代理网络一次前向约 1 毫秒——快约十万倍，但只在训练参数域内有效，落点出域就必须回退数值校准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>代理校准的配方：在参数网格上用原模型生成大量合成报价与目标——价格、希腊、隐波——训练网络逼近映射；精度验收用域内留出参数与域外落点检测两件套。</p><p><span class="marginnote">Horvath、Muguruza 与 Tomas 的两步法：先在参数网格上生成数十万级合成报价，再训网络学「参数到价格」，把波动率模型校准从分钟级数值优化降到毫秒级前向。精度以合成域内为准——落点出域，先检测再回退数值校准。</span>生成校准的配方：损失用签名 Wasserstein 或似然项，硬约束（正价格、无套利边界）用结构与投影施加，不指望损失自己学会；条件化——体制、宏观状态——进编码器与解码器两端，条件统计先于生成统计。验证走<a href="/quant/generative-backtest-eval">生成式回测评估</a>的协议：过程级统计（自相关、杠杆、波动聚集）加下游任务稳定性——策略排名随生成器种子要稳定。交付前冻结：生成器冻结之后，下游的对冲、风控与回测才许开始训练。</p>',12)),(B(),i(l,null,{default:t(()=>[A(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAR%5B%22%E5%8F%82%E6%95%B0%E7%BD%91%E6%A0%BC%22%5D%20--%3E%20SYN%5B%22%E5%8E%9F%E6%A8%A1%E5%9E%8B%E5%90%88%E6%88%90%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20SYN%20--%3E%20SUR%5B%22%E4%BB%A3%E7%90%86%E7%BD%91%E7%BB%9C%EF%BC%9A%E5%8F%82%E6%95%B0%E5%88%B0%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20MKT%5B%22%E5%B8%82%E5%9C%BA%E6%8A%A5%E4%BB%B7%20%2F%20%E5%8E%86%E5%8F%B2%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20CAL%5B%22%E5%8F%8D%E8%A7%A3%E5%8F%82%E6%95%B0%E6%88%96%E5%88%86%E5%B8%83%E6%8B%9F%E5%90%88%22%5D%0A%20%20SUR%20--%3E%20CAL%0A%20%20CAL%20--%3E%20GEN%5B%22%E5%8F%82%E6%95%B0%E8%90%BD%E7%82%B9%20%2F%20%E7%94%9F%E6%88%90%E5%99%A8%22%5D%0A%20%20GEN%20--%3E%20VAL%5B%22%E5%9F%9F%E5%86%85%E7%B2%BE%E5%BA%A6%20%2B%20%E8%BF%87%E7%A8%8B%E7%BA%A7%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20VAL%20--%3E%20FRZ%5B%22%E5%86%BB%E7%BB%93%E4%BA%A4%E4%BB%98%EF%BC%9A%E5%AF%B9%E5%86%B2%E4%B8%8E%E5%9B%9E%E6%B5%8B%E6%B6%88%E8%B4%B9%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("代理可行，机制在光滑性：价格对参数的映射在合理参数域内是光滑的，插值正是网络的强项；风险全在域外，所以覆盖与检测比容量重要。生成校准的机制变化更深：经典校准用几十个报价钉住一族测度，生成校准对齐的是整段过程的矩结构——匹配到二、三阶签名，杠杆与波动聚集才被迫出现。但无套利不由损失保证：生成器可以长出自相交的簿或负蝶式的曲面，下游网络会把这类伪影当成 alpha 吃掉，这是"),e("a",{href:"/quant/deep-hedging-buehler"},"深度对冲"),E("课预先警告过的接缝，下一课正面处理。")],-1)),a[5]||(a[5]=e("p",null,"两种校准的对照物与风险各记一本账：",-1)),(B(),i(l,null,{default:t(()=>[A(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E6%A0%A1%E5%87%86%E4%BB%80%E4%B9%88%3F%22%5D%20--%3E%20Proxy%5B%22%E4%BB%A3%E7%90%86%E6%A0%A1%E5%87%86%3A%20%E5%AD%A6%E5%8F%82%E6%95%B0%E5%88%B0%E4%BB%B7%E6%A0%BC%E7%9A%84%E6%98%A0%E5%B0%84%22%5D%0A%20%20Q%20--%3E%20Gen%5B%22%E7%94%9F%E6%88%90%E6%A0%A1%E5%87%86%3A%20%E7%9B%B4%E6%8E%A5%E6%8B%9F%E5%90%88%E8%B7%AF%E5%BE%84%E6%B5%8B%E5%BA%A6%22%5D%0A%20%20Proxy%20--%3E%20P1%5B%22%E8%AF%AF%E5%B7%AE%E8%B4%A6%3A%20%E4%B8%8E%E5%8E%9F%E6%A8%A1%E5%9E%8B%E4%BB%B7%E6%A0%BC%E5%B7%AE%2C%20%E5%9F%9F%E5%86%85%E5%AF%B9%E7%85%A7%22%5D%0A%20%20Gen%20--%3E%20G1%5B%22%E8%AF%AF%E5%B7%AE%E8%B4%A6%3A%20%E4%B8%8E%E7%9C%9F%E5%AE%9E%E5%B8%82%E5%9C%BA%E5%88%86%E5%B8%83%E5%B7%AE%2C%20%E7%95%99%E5%87%BA%E8%B7%AF%E5%BE%84%E5%AF%B9%E7%85%A7%22%5D%0A%20%20P1%20--%3E%20P2%5B%22%E9%A3%8E%E9%99%A9%3A%20%E8%90%BD%E7%82%B9%E5%87%BA%E5%9F%9F%E9%9D%99%E9%BB%98%E5%A4%96%E6%8E%A8%22%5D%0A%20%20G1%20--%3E%20G2%5B%22%E9%A3%8E%E9%99%A9%3A%20%E4%BC%AA%E5%BD%B1%E8%A2%AB%E4%B8%8B%E6%B8%B8%E5%BD%93%20alpha%2C%20P%2FQ%20%E6%B5%8B%E5%BA%A6%E6%B7%B7%E7%94%A8%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">常见误区：容易拿「生成的路径看起来像历史」当验收标准。分布距离小只说明统计像，不保证无套利——生成器完全可能长出负蝶式或自相交的簿，下游会把这些伪影当成 alpha 吃掉。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>生成器不替换生产定价器：香草曲面的日常报价仍归参数模型与数值法，生成校准的价值在路径依赖、压力情景与「一条历史不够用」的下游。小数据是硬边界：单条历史切窗带来的伪复制，窗口方案要写进实验记录，危机段单独条件化。校准对象变了，误差预算要重立：从贴报价的点误差，换成分布距离与下游决策稳定性的双指标——预算随用途定，不随架构定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>深度校准两形态：代理（学参数到价格的映射换速度）与生成（直接拟合路径测度换情景）。</li><li>两本误差账分开记：域内贴模型精度，分布距离对留出路径。</li><li>测度纪律先行：\\(\\mathbb{P}\\) 生成器产情景，\\(\\mathbb{Q}\\) 定价归参数模型，混用即系统性错误。</li><li>硬约束用结构施加；验证含过程级统计与下游稳定性，交付前冻结。</li><li>出处：Horvath, Muguruza and Tomas, <em>Quantitative Finance</em>, 2021；Wiese et al., <em>Quantitative Finance</em>, 2020（Quant GANs）；Kondratyev and Schwarz, <em>Risk</em>, 2019。</li></ul>',5))])}const q=s(p,[["render",u]]);export{D as __pageData,q as default};
